package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.FindAndModifyOptions;import org.springframework.data.mongodb.core.query.Criteria;import org.springframework.data.mongodb.core.query.Query;import org.springframework.data.mongodb.core.query.Update;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;
@Service public class PriceFreezeService{private final BookingRepository bookings;private final PriceFreezeRepository freezes;private final MongoTemplate mongo;@Value("${pricing.freeze-minutes:15}") private long minutes;public PriceFreezeService(BookingRepository b,PriceFreezeRepository f,MongoTemplate mongo){bookings=b;freezes=f;this.mongo=mongo;}public PriceFreeze create(String bookingId,String userId){Booking b=bookings.findById(bookingId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!userId.equals(b.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(b.getStatus()!=Booking.Status.CONFIRMED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only confirmed bookings can freeze a price");PriceFreeze p=new PriceFreeze();p.setBookingId(bookingId);p.setUserId(userId);p.setFrozenPrice(b.getTotalPrice());p.setExpiresAt(Instant.now().plusSeconds(minutes*60));return freezes.save(p);}public PriceFreeze get(String id,String user){PriceFreeze p=freezes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Price freeze not found"));if(!user.equals(p.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);expire(p);return freezes.save(p);}public PriceFreeze use(String id,String user){Instant now=Instant.now();Query active=new Query(Criteria.where("_id").is(id).and("userId").is(user).and("status").is(PriceFreeze.Status.ACTIVE).and("expiresAt").gt(now));PriceFreeze used=mongo.findAndModify(active,new Update().set("status",PriceFreeze.Status.USED),FindAndModifyOptions.options().returnNew(true),PriceFreeze.class);if(used!=null)return used;PriceFreeze p=get(id,user);if(p.getStatus()==PriceFreeze.Status.EXPIRED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Price freeze has expired");throw new ResponseStatusException(HttpStatus.CONFLICT,"Price freeze is not active");}private void expire(PriceFreeze p){if(p.getStatus()==PriceFreeze.Status.ACTIVE&&p.getExpiresAt()!=null&&p.getExpiresAt().isBefore(Instant.now()))p.setStatus(PriceFreeze.Status.EXPIRED);}}
